{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/feature-sticky.json
    A picture that stays in view while the feature descriptions scroll beside it. `active` marks the description that is current (the page follows the scroll; that is a port contract). Axes: mediaSide (end, start), item (plain, card), tone, density.
    Props (p): id, title, features, active, mediaSide, item, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_features = ($p['features'] ?? null)}
{var $v_active = ($p['active'] ?? '')}
{var $v_mediaSide = ($p['mediaSide'] ?? 'end')}
{var $v_item = ($p['item'] ?? 'plain')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_7}
  {capture $c_6}
    {capture $c_1}
      {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => $v_title, 'ratio' => '4/3']])|noescape}
    {/capture}
    {=ui_include('ui/box/box.latte', ['p' => ['Class' => ui_s(ui_cnv(['md:sticky md:top-8', (ui_t(ui_eq($v_mediaSide, 'start')) ? 'md:order-first' : 'md:order-last')])), 'Attrs' => ui_attrs(['data-testid', 'sticky-media'])], 'children' => $c_1])|noescape}
    {capture $c_5}
      {foreach ui_l($v_features) as $v_f}
        {capture $c_4}
          {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => ui_s(ui_get($v_f, ['icon'])), 'Size' => 24]])|noescape}
          {capture $c_2}
            {=ui_text(ui_get($v_f, ['title']))}
          {/capture}
          {=ui_include('ui/title/title.latte', ['p' => ['As' => ui_i(3), 'Size' => '2xl', 'Weight' => 'bold'], 'children' => $c_2])|noescape}
          {capture $c_3}
            {=ui_text(ui_get($v_f, ['text']))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'base', 'Class' => 'text-muted-foreground'], 'children' => $c_3])|noescape}
        {/capture}
        {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2', 'Class' => ui_s(ui_cnv([(ui_t(ui_eq($v_item, 'card')) ? 'rounded bg-card inset-ring inset-ring-border p-6' : 'py-4'), (ui_t(ui_eq(ui_get($v_f, ['id']), $v_active)) ? 'inset-ring inset-ring-foreground' : '')])), 'Attrs' => ui_attrs(['data-testid', 'item', 'aria-current', (ui_t(ui_eq(ui_get($v_f, ['id']), $v_active)) ? 'true' : null)])], 'children' => $c_4])|noescape}
      {/foreach}
    {/capture}
    {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => ui_s((ui_t(ui_eq($v_density, 'compact')) ? '4' : '8')), 'Align' => 'stretch', 'Attrs' => ui_attrs(['data-testid', 'items'])], 'children' => $c_5])|noescape}
  {/capture}
  {=ui_include('ui/grid/grid.latte', ['p' => ['Cols' => '1-2', 'Class' => 'items-start gap-8', 'Attrs' => ui_attrs(['data-testid', 'sticky'])], 'children' => $c_6])|noescape}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'density' => $v_density, 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_7])|noescape}
